from pathlib import Path
import json
root=Path("E:/WebAIBridge")
out={"root_exists":root.is_dir(),"children":[],"likely_files":[]}
if root.is_dir():
 try:
  out["children"]=[{"name":p.name,"directory":p.is_dir()} for p in root.iterdir() if p.name.lower() not in ("node_modules",".git",".env","logs",".secrets",".output")][:80]
  for sub in ("src","server","apps","packages","backend","web","services"):
   target=root/sub
   if not target.is_dir():continue
   files=[]
   for p in target.rglob("*"):
    if len(files)>=20:break
    if p.is_file() and p.suffix in (".js",".ts",".mjs",".cjs") and "node_modules" not in p.parts:
     if any(w in p.name.lower() for w in ("supervisor","watchdog","assignment","agent","server","api")):
      files.append(str(p.relative_to(root)))
   out["likely_files"]+=files
 except Exception as e:out["error_type"]=type(e).__name__
print(json.dumps(out,ensure_ascii=True))
